package org.opensaiclink.trial;
import java.util.*;
public final class FormalTest {
 static int checks;static void check(boolean ok,String msg){checks++;if(!ok)throw new AssertionError(msg);}
 static void rejects(Runnable r,String msg){try{r.run();throw new AssertionError(msg);}catch(IllegalArgumentException expected){checks++;}}
 public static void main(String[] args){
  Map<String,Object> old=new HashMap<>();old.put("car_shortcut_package","com.autonavi.amapauto");for(int i=1;i<=3;i++)old.put("car_shortcut_package_"+i,"com.example.app"+i);old.put("fill_display",true);
  HomeLayout migrated=HomeLayout.initial(0,"",old);check(migrated.get(2).equals("com.autonavi.amapauto"),"existing favorite remains in third cell");for(int i=1;i<=3;i++)check(migrated.get(i+5).equals("com.example.app"+i),"third row preserved");check(old.get("fill_display").equals(true),"legacy preferences untouched");
  HomeLayout edited=migrated.with(0,"com.example.navigation").move(0,8);check(HomeLayout.initial(1,edited.encode(),old).equals(edited),"migration never overwrites saved custom layout");check(HomeLayout.decode(edited.encode()).equals(edited),"serialization round trip includes blanks");check(edited.get(5).equals("#all"),"all-apps remains fixed during move");check(edited.get(8).equals("com.example.navigation"),"move reaches last editable slot");check(!migrated.equals(edited),"draft editing leaves original immutable");rejects(()->edited.with(5,"com.example.other"),"fixed tile cannot change");rejects(()->edited.move(5,0),"fixed tile cannot drag");rejects(()->HomeLayout.decode("broken"),"corrupt saved config detected");
  for(int from:HomeLayout.EDITABLE)for(int to:HomeLayout.EDITABLE){HomeLayout moved=migrated.move(from,to);check(moved.get(to).equals(migrated.get(from)),"move correct");check(moved.get(5).equals("#all"),"fixed slot protected");}
  SessionState s=new SessionState();check(!s.authorize(),"no connection cannot share");s.touch(true);check(s.connect(),"connect accepted");check(!s.connect(),"duplicate connect rejected");s.usb();check(!s.snapshot().canStart(),"USB alone is not handshake");s.configured();check(s.snapshot().canStart(),"connected and authorized ready");check(s.authorize(),"authorize once");check(!s.authorize(),"duplicate prompt rejected");s.cancelAuthorization();check(s.snapshot().canStart(),"cancel returns to ready");s.authorize();s.touch(false);check(!s.start(),"service loss between prompt and capture blocked");s.cancelAuthorization();s.touch(true);s.authorize();check(s.start(),"capture begins once");check(!s.start(),"duplicate start rejected");s.streaming();check(s.snapshot().projecting(),"streaming snapshot");s.pause(true);check(s.snapshot().stage==SessionState.Stage.PAUSED,"HU pause visible");s.pause(false);check(s.stop(),"stop starts cleanup");check(!s.stop(),"repeated stop idempotent");check(!s.connect(),"no reconnect while closing");s.ended(SessionState.Stage.DISCONNECTED,"USB detached");check(!s.snapshot().usb&&!s.snapshot().configured,"disconnect resets connection");check(s.connect(),"reconnect after cleanup allowed");s.stop();s.configured();check(s.snapshot().stage==SessionState.Stage.STOPPING,"late config cannot resurrect closing session");s.ended(SessionState.Stage.ERROR,"timeout");check(!s.start(),"stale capture cannot restart failed session");
  class Migration implements ConfigurationLogic.Migration {int version,writes;boolean backed,backupFail,installFail;String layout;public int version(){return version;}public Map<String,?> oldValues(){return old;}public boolean hasBackup(){return backed;}public boolean backup(){if(backupFail)return false;backed=true;return true;}public boolean install(String value){check(backed,"backup precedes migration commit");writes++;if(installFail)return false;layout=value;version=1;return true;}}
  Migration m=new Migration();m.backupFail=true;try{ConfigurationLogic.migrate(m);throw new AssertionError("backup failure must abort");}catch(IllegalStateException expected){check(m.writes==0 && m.version==0,"failed backup leaves old data untouched");}m.backupFail=false;m.installFail=true;try{ConfigurationLogic.migrate(m);throw new AssertionError("failed commit must abort");}catch(IllegalStateException expected){check(m.version==0,"failed install remains retryable");}m.installFail=false;ConfigurationLogic.migrate(m);check(m.version==1 && HomeLayout.decode(m.layout).equals(migrated),"retry migrates original settings");int writes=m.writes;ConfigurationLogic.migrate(m);check(m.writes==writes,"completed migration idempotent");
  class Recording implements ConfigurationLogic.Recording {boolean flag,fail;public boolean armed(){return flag;}public boolean disarm(){if(fail)return false;flag=false;return true;}}
  Recording recording=new Recording();check(!ConfigurationLogic.claim(recording),"recording off by default");recording.flag=true;recording.fail=true;check(!ConfigurationLogic.claim(recording),"failed disarm cannot start video recording");recording.fail=false;check(ConfigurationLogic.claim(recording),"explicit next session records");check(!ConfigurationLogic.claim(recording),"next session does not record again");
  System.out.println("PASS "+checks+" formal layout/migration/session assertions");
 }
}
